import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

export interface ManifestEntry {
  readonly name: string;
  readonly checksum: string;
  readonly size: number;
  readonly updatedAt: string;
}

export interface Manifest {
  readonly version: number;
  readonly entries: readonly ManifestEntry[];
}

export class ManifestStore {
  private readonly root: string;
  private cache: Manifest | undefined = undefined;

  constructor(root: string) {
    this.root = root;
  }

  private fileFor(name: string): string {
    return path.join(this.root, name + ".json");
  }

  private checksumOf(payload: string): string {
    return createHash("sha256").update(payload).digest("hex");
  }

  async list(): Promise<string[]> {
    const manifest = await this.readManifest("index");
    const names = manifest.entries.map((entry) => entry.name);
    return names.sort();
  }

  async load(name: string): Promise<ManifestEntry> {
    const manifest = await this.readManifest(name);
    const candidate = manifest.entries.find((entry) => entry.name === name);
    if (candidate === undefined) {
      throw new Error("missing entry for " + name);
    }
    return candidate;
  }

  async save(name: string, payload: string): Promise<void> {
    const file = this.fileFor(name);
    const previous = await this.readManifest(name);
    const entry: ManifestEntry = {
      name,
      checksum: this.checksumOf(payload),
      size: payload.length,
      updatedAt: new Date().toISOString(),
    };
    const kept = previous.entries.filter((candidate) => candidate.name !== name);
    const next: Manifest = {
      version: previous.version + 1,
      entries: [...kept, entry],
    };
    await writeFile(file, payload, "utf8");
    await this.writeManifest(name, next);
